import {esc,card} from './visuals.mjs';
export function signWorkerPosition(layout){
 const points={west:{x:180,y:110,ex:180,ey:50,label:'Western approach · roadside before the work area',facing:'Face traffic arriving from the west',sight:'M25 163 L170 118',arrow:'M35 175 H135'},east:{x:690,y:265,ex:690,ey:335,label:'Eastern approach · roadside before the work area',facing:'Face traffic arriving from the east',sight:'M780 202 L700 255',arrow:'M770 200 H710'},north:{x:450,y:80,ex:555,ey:80,label:'Northern approach · roadside before the junction',facing:'Face traffic arriving from the north',sight:'M410 10 L445 65',arrow:'M407 15 V60'}};
 const point=points[layout.entry]||points.west,reasons=[];
 if(layout.entry==='north'&&layout.template!=='corner')reasons.push('The straight-road template has no northern approach. Select a corner road or another approach.');
 if(layout.escape==='road')reasons.push('The selected escape route crosses traffic. Resolve this conflict before choosing a station.');
 if(layout.obstacle)reasons.push('An obstruction is present. Driver sight lines and the escape route need an on-site check; extra cameras do not resolve this check.');
 return {...point,hold:reasons.length>0,reasons};
}
export function renderSignWorkerPosition(site){const l=site.layout,p=signWorkerPosition(l),colour=p.hold?'#b04e32':'#967020';
 const select=(label,key,value,options)=>`<label class="ws-field">${label}<select data-ws-input="layout.${key}" aria-label="${label}">${options.map(([id,text])=>`<option value="${id}" ${id===value?'selected':''}>${text}</option>`).join('')}</select></label>`;
 return card('Warning-sign worker: proposed standing position','Planning aid · not to scale · field verification required',`<div class="card-body"><div class="ws-form">${select('Sign worker traffic approach','entry',l.entry,[['west','Western entry'],['east','Eastern entry'],['north','Northern corner']])}${select('Sign worker escape route','escape',l.escape,[['south','Away from traffic / same roadside'],['road','Across traffic (conflict demo)']])}</div><div class="sign-position-status ${p.hold?'hold':''}"><strong>${p.hold?'HOLD — position needs review':'Candidate position — not approved'}</strong><p>${esc(p.label)}. ${esc(p.facing)}.</p></div></div><svg class="ws-scene sign-position-diagram" viewBox="0 0 800 390" role="img" aria-label="Conceptual warning-sign worker station, approaching traffic, work area and proposed escape route"><defs><marker id="sign-route-arrow" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="none" stroke="context-stroke"/></marker></defs><rect width="800" height="390" fill="#edf3ef"/><path d="M0 180H800${l.template==='corner'?' M390 0V180':''}" fill="none" stroke="#526773" stroke-width="88"/><path d="M0 180H800" stroke="#b4c8c9" stroke-width="2" stroke-dasharray="12 10"/><rect x="475" y="235" width="175" height="65" rx="5" fill="#f2ce72" stroke="#957124"/><text x="492" y="264" font-size="16" fill="#443714">Work area</text><text x="492" y="284" font-size="13" fill="#443714">Other site workers</text>${l.obstacle?'<rect x="280" y="48" width="66" height="70" rx="4" fill="#9faea6"/><text x="260" y="36" font-size="14" fill="#4c5c52">Obstruction — check sight lines</text>':''}<path d="${p.arrow}" fill="none" stroke="#fff" stroke-width="4" marker-end="url(#sign-route-arrow)"/><path d="${p.sight}" fill="none" stroke="#b58b2c" stroke-width="3" stroke-dasharray="7 5"/>${l.entry==='north'&&l.template!=='corner'?'<text x="400" y="115" text-anchor="middle" font-size="18" fill="#a7412c">No northern approach in this template</text>':`<path d="M${p.x} ${p.y} L${p.ex} ${l.escape==='road'?180:p.ey}" fill="none" stroke="${l.escape==='road'?'#b04e32':'#237b68'}" stroke-width="3" stroke-dasharray="7 5" marker-end="url(#sign-route-arrow)"/><circle cx="${p.x}" cy="${p.y}" r="21" fill="#fff8de" stroke="${colour}" stroke-width="3"/><text x="${p.x}" y="${p.y+6}" text-anchor="middle" font-size="18" fill="#644912" font-weight="700">S</text><rect x="${p.x+25}" y="${p.y-21}" width="66" height="26" rx="4" fill="#f5cc54" stroke="#80631b"/><text x="${p.x+58}" y="${p.y-4}" text-anchor="middle" font-size="12" fill="#44320c">SIGN</text><path d="M${p.x+27} ${p.y+8}V${p.y+27}" stroke="#80631b" stroke-width="2"/><text x="${l.entry==='east'?p.x-120:p.x-85}" y="${p.y+45}" font-size="14" fill="#59491f">S · sign-holding worker</text><circle cx="${p.ex}" cy="${l.escape==='road'?180:p.ey}" r="8" fill="${l.escape==='road'?'#b04e32':'#237b68'}"/><text x="${p.ex-70}" y="${l.escape==='road'?205:p.ey+22}" font-size="13" fill="${l.escape==='road'?'#b04e32':'#237b68'}">${l.escape==='road'?'Conflict: live traffic':'Escape area to verify'}</text>`}<text x="24" y="373" font-size="14" fill="#4b6258">S = proposed station · dashed amber = sight line to check · green = proposed escape</text></svg><div class="card-body">${p.reasons.map(reason=>'<p class="ws-gap">'+esc(reason)+'</p>').join('')}<div class="sign-position-notes"><p><strong>Position to assess:</strong> a roadside station on the approach to the works, outside moving traffic, with the sign visible to approaching drivers.</p><p><strong>Before use:</strong> verify stopping sight distance, road speed, turning movements, pedestrians, clearance and an unobstructed escape path. The traffic management designer must determine the actual location and offsets in the site traffic guidance scheme.</p><p><strong>Role:</strong> this marker represents the person holding the warning sign, separate from the work crew. If they operate a STOP / SLOW bat, the traffic-controller training and approved site procedure apply. This demonstration does not authorise traffic control.</p></div><p class="note">Conceptual positions only; SCATS counts and Vicmap do not establish a safe standing location. These reference junctions may include traffic signals, trams and pedestrians that this diagram does not model. Sensor coverage confirmation does not approve this station.</p><p class="note">Guidance: <a href="https://austroads.gov.au/publications/temporary-traffic-management/agttm07" target="_blank" rel="noopener">Austroads — Traffic Controllers</a> · <a href="https://transport.vic.gov.au/road-and-active-transport/business-and-industry/temporary-traffic-management/training" target="_blank" rel="noopener">Transport Victoria — training</a>.</p></div>`);
}

